require_once __DIR__.'/../../includes/bootstrap.php';require_roles(['ADMIN','RESPONSABLE']);$rows=Database::connection()->query("SELECT c.numero_police,co.raison_sociale,p.nom,cm.base_calcul,cm.taux_applique,cm.montant,cm.date_exigibilite,cm.date_paiement,cm.statut FROM commissions cm JOIN contrats c ON c.id=cm.contrat_id JOIN souscriptions s ON s.id=c.souscription_id JOIN offres_devis o ON o.id=s.offre_id JOIN produits_assurance p ON p.id=o.produit_id JOIN compagnies co ON co.id=p.compagnie_id ORDER BY cm.date_exigibilite DESC")->fetchAll();audit('EXPORT_CSV','commissions');header('Content-Type: text/csv; charset=UTF-8');header('Content-Disposition: attachment; filename="assurcourt_commissions_'.date('Ymd').'.csv"');echo "\xEF\xBB\xBF";$out=fopen('php://output','w');fputcsv($out,['Police','Compagnie','Produit','Base','Taux','Montant','Exigibilité','Paiement','Statut'],';');foreach($rows as $r)fputcsv($out,$r,';');fclose($out);exit;
